(() => {
'use strict';const $=s=>document.querySelector(s),reduce=matchMedia('(prefers-reduced-motion: reduce)'),opening=$('.opening'),studio=$('.studio'),world=$('.world'),friends=$('.friends');let scene,scheduled=0;
const clamp=v=>Math.max(0,Math.min(1,v));
function update(){scheduled=0;const p=reduce.matches?0:clamp(-opening.getBoundingClientRect().top/(opening.offsetHeight-innerHeight));studio.style.setProperty('--p',p.toFixed(4));studio.dataset.progress=p.toFixed(3);scene?.progress(p);const w=clamp(-world.getBoundingClientRect().top/Math.max(1,world.offsetHeight-$('.city-frame').offsetHeight));$('.city-frame').style.setProperty('--p',reduce.matches?1:w.toFixed(4));friends.style.setProperty('--p',reduce.matches?1:clamp((innerHeight-friends.getBoundingClientRect().top)/(innerHeight+friends.offsetHeight)).toFixed(4));}
function schedule(){update()}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});reduce.addEventListener('change',schedule);update();
let busy=false;$('#nudge').addEventListener('click',()=>{if(busy)return;busy=true;scene?.nudge();$('#reaction-status').textContent='CONK jumps with surprise!';$('.impact').animate([{opacity:0,transform:'rotate(-15deg) scale(.3)'},{opacity:1,transform:'rotate(-10deg) scale(1.1)',offset:.25},{opacity:1,transform:'rotate(-10deg) scale(1)',offset:.65},{opacity:0,transform:'translateY(-30px) rotate(-10deg) scale(1.1)'}],{duration:900,easing:'cubic-bezier(.2,.7,.3,1)'});if(!scene&&!reduce.matches)$('.poster img').animate([{transform:'translateY(0)'},{transform:'translateY(-60px) rotate(12deg)',offset:.4},{transform:'translateY(0)'}],{duration:800,easing:'ease-out'});setTimeout(()=>busy=false,1000)});
const load=()=>import('./scene.js').then(m=>m.initScene($('#renderer'),{reduce:reduce.matches})).then(s=>{scene=s;studio.classList.add('model-ready');$('#renderer').dataset.ready='true';update()}).catch(()=>{$('#interaction-hint').textContent='Tap for a little chaos';$('#renderer').style.pointerEvents='none'});
if('requestIdleCallback' in window)requestIdleCallback(load,{timeout:900});else setTimeout(load,450);
$('#copy-button').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#contract-address').textContent);$('#copy-button').textContent='Copied!';$('#copy-status').textContent='Contract address copied.';setTimeout(()=>$('#copy-button').textContent='Copy address',2000)}catch{const range=document.createRange();range.selectNodeContents($('#contract-address'));getSelection().removeAllRanges();getSelection().addRange(range);$('#copy-status').textContent='Select and copy the contract address.';$('#copy-button').textContent='Select address'}});
})();